@Component("security-handler")
@ProcessingGroup("security-processing-group")
public class SecurityEventHandler {
	
	// core constructor
	SecurityEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateSecurityEvent
     */
    @EventHandler
    public void handle( CreateSecurityEvent event) {
        entityManager.persist(new Security(event.getSecurityId(), event.getSymbol(), event.getIsin(), event.getCusip(), event.getCurrency(), event.getPositions(), event.getTrades(), event.getOrders(), event.getSecurityType()));
    }

    /*
     * @param	event UpdateSecurityEvent
     */
    @EventHandler
    public Security handle( UpdateSecurityEvent event) {
    	entityManager.merge(new Security(event.getSecurityId(), event.getSymbol(), event.getIsin(), event.getCusip(), event.getCurrency(), event.getPositions(), event.getTrades(), event.getOrders(), event.getSecurityType()));
    }
    
    /*
     * @param	event DeleteSecurityEvent
     */
    @EventHandler
    public void on( DeleteSecurityEvent event) {
    	Security entity = new Security();
   
    	// ------------------------------------------
    	// apply the SecurityId
    	// ------------------------------------------
    	entity.setSecurityId( event.getSecurityId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final SecurityRepository securityEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(SecurityEventHandler.class.getName());

}
